import json
from pathlib import Path

output_dir = Path("/home/cdsw/data/agent/runs/inv-20261021-184608")
logs = {}

for name, info in subagent_info.items():
    log_file = Path(info["session_dir"]) / "session.log"
    if log_file.exists():
        with open(log_file, "r") as f:
            logs[name] = f.read()
    else:
        logs[name] = "Log file not found."

# Extract any results or errors from the logs
results = {}
for name, log in logs.items():
    if "{" in log and "}" in log:
        # Try to locate JSON-like output in the log
        start = log.find("{")
        end = log.rfind("}") + 1
        if start != -1 and end != -1:
            try:
                json_str = log[start:end]
                results[name] = json.loads(json_str)
            except json.JSONDecodeError:
                results[name] = "Failed to parse output from log."
    else:
        results[name] = "No output found in log."

# Output the logs and results
{
    "logs_snippets": {name: log[-1000:] for name, log in logs.items()},
    "results": results
}

